<script setup lang="ts">
import {onMounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {usePayrollPage} from '../payrollPage'
import {validEvidencePage,validCompanySdl,validRemittance,validSettlement} from '../settlementResponses'
import {useSettlementCommand} from '../settlementCommand'
import {validMonth} from '../payrollUi'
import {storeToday} from '../time'
import {settlementAmount} from '../supplemental'
import type {SettlementEvidence,SettlementEvidencePage,Remittance,RemittanceWrite,ReconciliationPage,CompanySdl,CompanySdlEvidence,SettlementRecord} from '../supplemental'
import type {PayrollHomeData,PayProfilePage} from '../payrollTypes'
import type {Option} from '../types'
import PhaseStatus from '../components/PhaseStatus.vue'
import AnnualWagePanel from '../components/AnnualWagePanel.vue'
import StatutoryBalanceTable from '../components/StatutoryBalanceTable.vue'
import SettlementEvidenceEditor from '../components/SettlementEvidenceEditor.vue'
import StatutoryRemittanceEditor from '../components/StatutoryRemittanceEditor.vue'
import SettlementSnapshot from '../components/SettlementSnapshot.vue'
import CompanySdlFacts from '../components/CompanySdlFacts.vue'
const route=useRoute(),{api,home,english,base,loading,failure,notice,load}=usePayrollPage(),command=useSettlementCommand(),{locked,uncertain,busy:commandBusy,failure:commandFailure}=command,x=(z:string,e:string)=>english()?e:z,money=(v:string|null|undefined)=>settlementAmount(v,english())
const directory=ref<PayrollHomeData|null>(null),company=ref(String(route.query.companyId||'')),employees=ref<Option[]>([]),employee=ref(''),month=ref(storeToday().slice(0,7)),facts=ref<SettlementEvidencePage|null>(null),sdl=ref<CompanySdl|null>(null),reconciliations=ref<ReconciliationPage[]>([]),remittances=ref<Remittance[]>([]),note=ref(''),evidenceKey=ref(0),remittanceKey=ref(0),annualRevision=ref(0),lastSettlement=ref<SettlementRecord|null>(null)
watch(command.errorCode,code=>{if(['SUPPLEMENTAL_SOURCE_CHANGED','AW_CONTEXT_STALE','WORKFORCE_PAYROLL_SOURCE_CHANGED'].includes(code))clearFacts()})
let selectionRevision=0
function invalidateReads(){selectionRevision++;reconciliations.value=[]}
watch(command.busy,value=>{if(value){invalidateReads();annualRevision.value++}},{flush:'sync'})
function clearFacts(){invalidateReads();lastSettlement.value=null;facts.value=null;sdl.value=null;reconciliations.value=[];annualRevision.value++}
watch([employee,month,company],clearFacts)
function refresh(){if(locked.value)return;clearFacts();employees.value=[];remittances.value=[];return load(async()=>{const d=await api().get<PayrollHomeData>('/payroll-home'),id=d.companies.find(c=>c.id===company.value)?.id||d.companies[0]?.id||'';const [p,r]=id?await Promise.all([api().get<PayProfilePage>('/pay-profiles?companyId='+id),api().get<Remittance[]>('/statutory-remittances?companyId='+id)]):[{employees:[]},[]];return {d,id,p,r}},v=>{directory.value=v.d;company.value=v.id;employees.value=v.p.employees;employee.value=v.p.employees.some(e=>e.id===employee.value)?employee.value:v.p.employees[0]?.id||'';remittances.value=v.r})}
function readFacts(){if(locked.value||!company.value||!employee.value||!validMonth(month.value))return;facts.value=null;sdl.value=null;const rev=selectionRevision,capturedCompany=company.value,capturedEmployee=employee.value,capturedMonth=month.value;return load(async()=>{const [f,s]=await Promise.all([api().get<SettlementEvidencePage>(`/statutory-settlement-contexts/${capturedCompany}/${capturedEmployee}/${capturedMonth}`),api().get<CompanySdl>(`/statutory-company-months/${capturedCompany}/${capturedMonth}`)]);return {f,s,company:company.value,employee:employee.value,month:month.value}},v=>{if(rev!==selectionRevision||v.f.companyId!==company.value||v.f.employeeId!==employee.value||v.f.month!==month.value||v.s.companyId!==company.value||v.s.month!==month.value)return;facts.value=v.f;sdl.value=v.s;evidenceKey.value++})}
function saveFacts(body:SettlementEvidence){if(!facts.value?.writable||!home.value?.headOffice||locked.value)return;return command.run<SettlementEvidencePage>(`/statutory-settlement-contexts/${company.value}/${employee.value}/${month.value}`,body,'put',v=>validEvidencePage(v,company.value,employee.value,month.value),v=>{invalidateReads();facts.value=v;evidenceKey.value++;reconciliations.value=[];annualRevision.value++})}
function settleFacts(){if(locked.value||!home.value?.headOffice||!facts.value?.writable||!facts.value.fingerprint||!note.value.trim())return;const original=facts.value;return command.run<SettlementRecord>(`/statutory-settlement-contexts/${company.value}/${employee.value}/${month.value}/settlements`,{commandId:crypto.randomUUID(),expectedFingerprint:original.fingerprint,note:note.value.trim()},'post',v=>validSettlement(v,company.value,employee.value,null,Number(month.value.slice(0,4))),v=>{lastSettlement.value=v;invalidateReads();facts.value=null;sdl.value=null;reconciliations.value=[];annualRevision.value++;notice.value=x('原少缴责任已结算；未增加工资收入，实际缴纳仍须单独登记。','Original shortfall liability settled without new wages; actual remittances require separate registration.')})}
function saveSdl(body:CompanySdlEvidence){if(!sdl.value?.writable||!home.value?.headOffice||locked.value)return;return command.run<CompanySdl>(`/statutory-company-months/${company.value}/${month.value}`,body,'put',v=>validCompanySdl(v,company.value,month.value),v=>{invalidateReads();sdl.value=v;reconciliations.value=[];annualRevision.value++;evidenceKey.value++})}
function readReconciliations(){if(locked.value||!employee.value||!validMonth(month.value))return;reconciliations.value=[];const rev=selectionRevision;return load(()=>api().get<ReconciliationPage[]>(`/aw-reconciliations?companyId=${company.value}&employeeId=${employee.value}&year=${month.value.slice(0,4)}`),v=>{if(rev!==selectionRevision)return;reconciliations.value=v.filter(p=>p.reconciliation.companyId===company.value&&p.reconciliation.employeeId===employee.value&&p.reconciliation.year===Number(month.value.slice(0,4)))})}
function settle(p:ReconciliationPage){if(locked.value||p.settled||!home.value?.headOffice||!note.value.trim())return;return command.run<SettlementRecord>(`/aw-reconciliations/${p.reconciliation.id}/settlements`,{commandId:crypto.randomUUID(),expectedFingerprint:p.reconciliation.assessment.fingerprint,note:note.value.trim()},'post',v=>validSettlement(v,company.value,employee.value,p.reconciliation.id,p.reconciliation.year),v=>{lastSettlement.value=v;invalidateReads();reconciliations.value=[{...p,settled:true,balances:v.balances}];facts.value=null;sdl.value=null})}
function saveRemittance(id:string,body:RemittanceWrite){if(locked.value)return;return command.run<Remittance>('/statutory-remittances/'+id,body,'put',v=>validRemittance(v,id,company.value),v=>{invalidateReads();remittances.value=[v,...remittances.value.filter(r=>r.id!==v.id)];facts.value=null;sdl.value=null;reconciliations.value=[];remittanceKey.value++;annualRevision.value++})}
onMounted(()=>void refresh())
</script>
<template><section class="wf-panel"><header class="wf-toolbar"><h2>{{x('法定事实与独立结算','Statutory facts and independent settlement')}}</h2><button :disabled="locked||loading" @click="refresh">{{x('刷新结算工作台','Refresh settlement workbench')}}</button></header><PhaseStatus :failure="failure||commandFailure" :notice="notice" :loading="loading||commandBusy"/><p v-if="uncertain" role="alert">{{x('提交结果尚未确认；事实、分配与上下文已锁定。','Result unconfirmed; facts, allocations and context are locked.')}} <button :disabled="commandBusy" @click="command.replay">{{x('重试原命令','Retry exact command')}}</button></p><fieldset :disabled="locked||loading"><div class="wf-grid"><label>{{x('公司','Company')}}<select v-model="company" :aria-label="x('结算公司','Settlement company')" @change="refresh"><option v-for="c in directory?.companies||[]" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>{{x('员工','Employee')}}<select v-model="employee" :aria-label="x('结算员工','Settlement employee')"><option v-for="e in employees" :key="e.id" :value="e.id">{{e.name}}</option></select></label><label>{{x('原贡献月份','Original contribution month')}}<input v-model="month" type="month" :aria-label="x('结算原月份','Settlement origin month')"></label></div><button :disabled="!employee||!validMonth(month)" @click="readFacts">{{x('读取原事实与余额','Load original facts and balances')}}</button></fieldset><p v-if="directory&&!directory.companies.length">{{x('无完整公司工资权限。','No full company payroll access.')}}</p><RouterLink :to="{path:base+'/supplemental-payroll',query:{companyId:company}}">{{x('独立补发工资','Supplemental payroll')}}</RouterLink><label v-if="company&&employee">{{x('责任结算说明','Liability settlement note')}}<textarea v-model="note" :disabled="locked" maxlength="1000" :aria-label="x('责任结算说明','Liability settlement note')"/></label><template v-if="facts"><StatutoryBalanceTable :balances="[facts.balance]"/><button v-if="home?.headOffice&&facts.writable&&facts.fingerprint" :disabled="locked||!note.trim()" @click="settleFacts">{{x('结算原少缴责任（不新增工资）','Settle original statutory shortfall (no new wages)')}}</button><SettlementEvidenceEditor v-if="home?.headOffice&&facts.writable" :key="'facts-'+evidenceKey" :page="facts" :locked="locked" :reconciliations="reconciliations" :reconciliations-loading="loading" @load-reconciliations="readReconciliations" @save="saveFacts"/><p v-else>{{x('仅可读取事实；总部且具有完整公司工资权限才可维护。','Facts are read only; headquarters with full company payroll scope can maintain them.')}}</p></template><CompanySdlFacts v-if="sdl" :key="'sdl-'+evidenceKey" :page="sdl" :employees="employees" :head-office="!!home?.headOffice" :locked="locked" @save="saveSdl"/><template v-if="company&&employee&&validMonth(month)"><fieldset :disabled="locked"><AnnualWagePanel :company-id="company" :employee-id="employee" :year="Number(month.slice(0,4))" :source-version="annualRevision" @changed="invalidateReads"/></fieldset><section class="wf-section"><h3>{{x('不可变年度AW复核与责任结算','Immutable annual AW review and liability settlement')}}</h3><p>{{x('先读取原年度资料并记录复核；此处只消费服务器保存的assessment，不增加工资、SDL或CDAC，也不登记真实缴纳。','Review annual sources and record a reconciliation first. Settlement consumes the stored assessment without new wages, SDL, CDAC or actual remittances.')}}</p><button :disabled="locked||loading" @click="readReconciliations">{{x('读取年度复核记录','Load annual reconciliations')}}</button><article v-for="p in reconciliations" :key="p.reconciliation.id" class="wf-section"><p>{{x('结算月份','Settlement month')}} {{p.reconciliation.settlementMonth}} · {{p.settled?x('责任修订已结算；实缴另行登记','Liability revision settled; remittance recorded separately'):x('责任修订待结算','Liability revision pending')}}</p><p>{{x('员工／雇主／总责任差额（独立保留）','Employee / employer / total liability difference (kept separate)')}}: {{money(p.reconciliation.assessment.employeeDelta)}} / {{money(p.reconciliation.assessment.employerDelta)}} / {{money(p.reconciliation.assessment.totalDelta)}}</p><details><summary>{{x('原不可变评估及指纹','Original immutable assessment and fingerprint')}}</summary><p>{{p.reconciliation.id}} · {{p.reconciliation.assessment.fingerprint}}</p><p v-for="m in p.reconciliation.assessment.months" :key="m.month">{{m.month}} · {{x('员工／雇主差额','Employee / employer difference')}} {{money(m.employeeDelta)}} / {{money(m.employerDelta)}} · {{m.issues.join(' · ')}}</p></details><StatutoryBalanceTable :balances="p.balances"/><button v-if="home?.headOffice&&!p.settled" :disabled="locked||!note.trim()||p.reconciliation.assessment.status!=='ready'" @click="settle(p)">{{x('结算该次责任修订','Settle this liability revision')}}</button></article></section></template><SettlementSnapshot v-if="lastSettlement" :record="lastSettlement"/><template v-if="company"><StatutoryRemittanceEditor :key="company+'-'+remittanceKey" :company-id="company" :employees="employees" :remittances="remittances" :locked="locked" @save="saveRemittance"/><section class="wf-section"><h3>{{x('实际缴纳记录','Actual remittance records')}}</h3><article v-for="r in remittances" :key="r.id"><p>{{r.paymentDate}} · {{r.reference}} · {{r.reversesId?x('整笔冲正','Full reversal'):x('已登记','Recorded')}}</p><p v-for="(a,i) in r.allocations" :key="i">{{a.employeeId?employees.find(e=>e.id===a.employeeId)?.name||a.employeeId:x('公司','Company')}} · {{a.month}} · {{a.component}} · {{a.amount}}</p></article><p v-if="!remittances.length">{{x('没有本系统新登记记录；不能据此推断历史未缴。','No new remittances recorded here; this does not imply historical non-payment.')}}</p></section></template></section></template>
<style scoped>p,dd{overflow-wrap:anywhere}fieldset{min-width:0}</style>
